<section class="section"><header class="admin-header"><h1><?php echo $editing ? 'Editar cliente' : 'Clientes'; ?></h1><a href="customer_create.php" class="btn">Nuevo cliente</a></header><?php if (!empty($error)): ?><p class="alert alert--error"><?php echo htmlspecialchars($error, ENT_QUOTES, 'UTF-8'); ?></p><?php endif; ?><?php if ($editing): ?><form method="post" class="admin-form"><label>Nombre<input name="name" required value="<?php echo htmlspecialchars($customer?->name ?? '', ENT_QUOTES, 'UTF-8'); ?>"></label><label>Teléfono<input name="phone" required value="<?php echo htmlspecialchars($customer?->phone ?? '', ENT_QUOTES, 'UTF-8'); ?>"></label><label>Correo<input type="email" name="email" value="<?php echo htmlspecialchars($customer?->email ?? '', ENT_QUOTES, 'UTF-8'); ?>"></label><label>Empresa<input name="business_name" value="<?php echo htmlspecialchars($customer?->businessName ?? '', ENT_QUOTES, 'UTF-8'); ?>"></label><label>Tipo<select name="customer_type"><option value="persona_fisica">Persona física</option><option value="persona_moral" <?php echo ($customer?->customerType ?? '') === 'persona_moral' ? 'selected' : ''; ?>>Persona moral</option></select></label><button class="btn">Guardar</button></form><?php else: ?><p>Consulta y administra los clientes registrados desde el panel.</p><?php endif; ?></section>
